'use strict';
(()=>{
const ID='G-WJ4KERSCRC',KEY='idol-antenna.analytics.disabled';
const url=new URL(location.href),choice=url.searchParams.get('analytics');
try{if(choice==='off')localStorage.setItem(KEY,'1');if(choice==='on')localStorage.removeItem(KEY);}catch{}
let disabled=choice==='off';try{disabled=disabled||localStorage.getItem(KEY)==='1';}catch{}
const test=choice==='test',enabled=!disabled&&!test&&!navigator.webdriver&&url.hostname==='sakura-essays.github.io'&&url.pathname.startsWith('/idol-kosatsu-antenna/');
window['ga-disable-'+ID]=!enabled;
const clean=s=>{const t=String(s||'').normalize('NFKC').replace(/\s+/g,' ').trim();return /@|https?:|www\.|(?:\d[\s()+-]*){7,}/i.test(t)?'[redacted]':t.slice(0,100)};
const mode=url.pathname.endsWith('/about.html')?'about':url.pathname.endsWith('/writers.html')?'authors':url.pathname.includes('/authors/')?'author_page':'articles';
let state={},count=0,lastSearch='',timer=null,observer=null;const records=[],seen=new Set(),timers=new Map();
const referrer=()=>{try{const r=new URL(document.referrer);return r.origin+r.pathname}catch{return ''}};
const base=()=>({site_view:mode,filter_category:state.category||'all',filter_group:state.group||'all',filter_topic:state.topic||'all',sort_order:state.sort||'balanced',search_term:clean(state.q),search_scope:mode==='authors'?'authors':'articles',result_count:count,measurement_version:'20261117'});
function debug(){if(!document.body)return;let n=document.getElementById('analytics-debug');if(!n){n=document.createElement('details');n.id='analytics-debug';n.open=true;n.innerHTML='<summary>GA4テスト（送信しません）</summary><pre></pre>';document.body.append(n)}n.querySelector('pre').textContent=JSON.stringify(records.slice(-25),null,2)}
function track(event,p={}){if(!enabled&&!test)return;const data={...base(),...p,page_location:location.origin+location.pathname};if(test){records.push({event,...data});debug()}else window.gtag('event',event,data)}
function flush(){clearTimeout(timer);if(!String(state.q||'').trim()){lastSearch='';return}const sig=JSON.stringify([state.q,state.category,state.group,state.topic,state.era,count,mode]);if(sig===lastSearch)return;lastSearch=sig;track(mode==='authors'?'writer_search':'view_search_results',{zero_results:String(count===0)})}
function article(link){const d=window.ANTENNA||{},a=(d.articles||[]).find(x=>x.url===link.href),w=(d.authors||[]).find(x=>x.id===a?.author_id);return {link_url:link.href,article_id:a?.id||'',article_title:(a?.title||link.textContent||'').slice(0,100),author_id:a?.author_id||'',author_name:w?.name||'',article_group:(a?.group_ids||[]).join(' / '),placement:link.closest('#pickup-list')?'pickup':link.closest('#draw-result')?'random':mode==='author_page'?'author_page':'list'}}
function observe(){if(!observer)return;observer.disconnect();for(const t of timers.values())clearTimeout(t);timers.clear();document.querySelectorAll('.article h3 a[href]').forEach(link=>observer.observe(link))}
function update(next,results){const old=JSON.stringify([state.category,state.group,state.topic,state.era,state.sort]),was=Boolean(Object.keys(state).length),oldQ=state.q;state={...next};count=Number(results)||0;if(was&&old!==JSON.stringify([state.category,state.group,state.topic,state.era,state.sort]))track('filter_change');if(oldQ!==state.q){clearTimeout(timer);if(String(state.q||'').trim())timer=setTimeout(flush,750);else lastSearch=''}observe()}
function init(){track('page_view',{page_title:document.title,page_referrer:referrer()});if(typeof IntersectionObserver==='function')observer=new IntersectionObserver(entries=>{for(const e of entries){const link=e.target,key=[mode,state.q,state.category,state.group,link.href,link.closest('#draw-result')?'random':'list'].join('|');if(!e.isIntersecting||e.intersectionRatio<0.5){clearTimeout(timers.get(link));timers.delete(link);continue}if(seen.has(key)||timers.has(link))continue;timers.set(link,setTimeout(()=>{timers.delete(link);if(!link.isConnected||document.visibilityState==='hidden')return;seen.add(key);track('article_impression',article(link))},1000))}},{threshold:[0,0.5]});for(const kind of ['click','auxclick'])document.addEventListener(kind,e=>{if(kind==='click'&&e.button>0||kind==='auxclick'&&e.button!==1)return;const link=e.target.closest?.('.article h3 a[href]');if(!link)return;flush();track('article_click',{...article(link),open_method:kind==='auxclick'?'middle':e.ctrlKey||e.metaKey?'modified':'normal'})});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){flush();for(const t of timers.values())clearTimeout(t);timers.clear()}else observe()});observe();debug()}
if(enabled){window.dataLayer=window.dataLayer||[];window.gtag=function(){window.dataLayer.push(arguments)};window.gtag('js',new Date());window.gtag('config',ID,{send_page_view:false,page_location:location.origin+location.pathname,page_referrer:referrer(),allow_google_signals:false,allow_ad_personalization_signals:false});const s=document.createElement('script');s.async=true;s.src='https://www.googletagmanager.com/gtag/js?id='+ID;document.head.append(s)}
window.AntennaAnalytics={track,update,flushSearch:flush,observe,enabled,mode:test?'test':enabled?'on':'off',events:records};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();